{
 "modules": [
  {
   "id": "eligibility_trace",
   "name": "Eligibility Trace",
   "description": "Maintains a decaying eligibility trace to update previously visited state-action pairs in the RL system.",
   "params": [
    {
     "name": "lambda_trace",
     "bounds": [
