   ]
  },
  {
   "id": "global_action_stickiness",
   "name": "Action Stickiness",
   "description": "Adds a bias to the RL value of the previously chosen action to model choice perseveration.",
   "params": [
    {
     "name": "kappa_global_stick",
     "bounds": [
      -10,
      10
     ]
    }
   ],
   "slots": {
    "block_init": "global_action_stickiness_last = -1",
    "pre_choice": "global_action_stickiness_bias = np.zeros(nA)\nif global_action_stickiness_last >= 0:\n    global_action_stickiness_bias[global_action_stickiness_last] = kappa_global_stick",
