   "params": [],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    w[s, :] = 1e-6\n    w[s, a] = 1.0 - (nA - 1) * 1e-6\nelse:\n    w[s, :] = (1.0 - 0.05) * w[s, :] + 0.05 * w_0[s, :]"
