   "slots": {},
   "overrides": {
    "wm_values": "(1.0 - np.clip(1.0 / (1.0 + np.exp(-noise_gain_retrieval * (nS - 3.0))), 0.0, 1.0)) * w[s] + np.clip(1.0 / (1.0 + np.exp(-noise_gain_retrieval * (nS - 3.0))), 0.0, 1.0) * w_0[s]"
