  {
   "id": "wm_asymmetric_update_p2",
   "name": "Asymmetric WM Update (P2)",
   "description": "WM values are updated toward the chosen action upon reward, and decay toward uniform upon non-reward.",
   "params": [],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    w[s, :] = 0.9 * w[s, :]\n    w[s, a] += 0.1\nelse:\n    w[s, :] = 0.95 * w[s, :] + 0.05 * w_0[s, :]\nwm_asymmetric_update_p2_sum = np.sum(w[s, :])\nif wm_asymmetric_update_p2_sum > 0:\n    w[s, :] /= wm_asymmetric_update_p2_sum\nelse:\n    w[s, :] = w_0[s, :]"
