    "init": "outcome_gated_wm_reliance_g = 0.0",
    "pre_choice": "outcome_gated_wm_reliance_eps = 1e-12\noutcome_gated_wm_reliance_logit = np.log(np.clip(wm_weight, outcome_gated_wm_reliance_eps, 1-outcome_gated_wm_reliance_eps)) - np.log(np.clip(1-wm_weight, outcome_gated_wm_reliance_eps, 1-outcome_gated_wm_reliance_eps))\noutcome_gated_wm_reliance_eff = 1.0 / (1.0 + np.exp(-(outcome_gated_wm_reliance_logit + outcome_gated_wm_reliance_g)))",
    "update_extra": "outcome_gated_wm_reliance_target = win_boost if r > 0.5 else -loss_suppression\noutcome_gated_wm_reliance_g = (1.0 - kappa_gate) * outcome_gated_wm_reliance_g + kappa_gate * outcome_gated_wm_reliance_target"
