    "wm_update": "if r > 0.5:\n    unified_wm_update_decay_one_hot = np.zeros(nA)\n    unified_wm_update_decay_one_hot[a] = 1.0\n    w[s, :] = (1.0 - kappa_wm) * w[s, :] + kappa_wm * unified_wm_update_decay_one_hot\nelse:\n    w[s, :] = (1.0 - kappa_wm) * w[s, :] + kappa_wm * w_0[s, :]"
