  {
   "id": "surprise_confidence_wm_boost",
   "name": "Surprise and Confidence Gated WM Arbitration",
   "description": "The trial-by-trial working memory mixture weight is dynamically boosted by the product of the absolute RL prediction error and the confidence of the WM state.",
   "params": [
    {
     "name": "surprise_gate",
     "bounds": [
      0,
      5
     ]
