   ],
   "slots": {
    "init": "surprise_confidence_wm_boost_pe = 0.0",
    "pre_choice": "surprise_confidence_wm_boost_sorted = np.sort(w[s])[::-1]\nsurprise_confidence_wm_boost_val = max(0.0, surprise_confidence_wm_boost_sorted[0] - (surprise_confidence_wm_boost_sorted[1] if len(surprise_confidence_wm_boost_sorted) > 1 else 0.0))\nsurprise_confidence_wm_boost_boost = surprise_gate * abs(surprise_confidence_wm_boost_pe) * surprise_confidence_wm_boost_val",
