    "load_scaled_wm_weight",
    "pe_based_arbitration",
    "dynamic_arbitration"
   ]
  },
  {
   "id": "prob_preserving_wm_update",
   "name": "Probability-Preserving WM Update",
   "description": "Working memory updates maintain a probability distribution by shifting mass toward the chosen action on reward, and distributing mass from the chosen action equally to unchosen actions on error.",
   "params": [
    {
     "name": "wm_alpha",
     "bounds": [
      0,
      1
     ]
    }
   ],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    w[s, :] = (1.0 - wm_alpha) * w[s, :]\n    w[s, a] += wm_alpha\nelse:\n    prob_preserving_wm_update_reduce = wm_alpha * min(1.0, w[s, a])\n    w[s, a] = max(0.0, w[s, a] - prob_preserving_wm_update_reduce)\n    prob_preserving_wm_update_inc = prob_preserving_wm_update_reduce / (nA - 1)\n    for prob_preserving_wm_update_aa in range(nA):\n        if prob_preserving_wm_update_aa != a:\n            w[s, prob_preserving_wm_update_aa] += prob_preserving_wm_update_inc\nprob_preserving_wm_update_sum = np.sum(w[s, :])\nif prob_preserving_wm_update_sum > 0:\n    w[s, :] /= prob_preserving_wm_update_sum\nelse:\n    w[s, :] = w_0[s, :]"
