    "asymmetric_fixed_wm_update",
    "arbitration_gated_wm_learning"
   ]
  },
  {
   "id": "state_action_stickiness",
   "name": "Choice perseveration",
   "description": "Adds an additive bias to the RL Q-value of the last action taken in the current state.",
   "params": [
    {
     "name": "stay_bias",
     "bounds": [
      -10,
      10
     ]
    }
   ],
   "slots": {
    "block_init": "state_action_stickiness_last_action = -np.ones(nS, dtype=int)",
    "pre_choice": "state_action_stickiness_bias = np.zeros(nA)\nif state_action_stickiness_last_action[s] >= 0:\n    state_action_stickiness_bias[state_action_stickiness_last_action[s]] = stay_bias",
