    {
     "name": "wm_lr",
     "bounds": [
      0,
      1
     ]
    },
    {
     "name": "confusion_rate",
     "bounds": [
      0,
      1
     ]
    }
   ],
   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    load_dependent_wm_learning_conf = 1.0 - (1.0 - np.clip(confusion_rate, 0.0, 1.0)) ** max(1, nS)\n    load_dependent_wm_learning_target = np.ones(nA) * (load_dependent_wm_learning_conf / (nA - 1))\n    load_dependent_wm_learning_target[a] = 1.0 - load_dependent_wm_learning_conf\nelse:\n    load_dependent_wm_learning_target = w_0[s, :].copy()\nw[s, :] = (1.0 - wm_lr) * w[s, :] + wm_lr * load_dependent_wm_learning_target"
