   "slots": {},
   "overrides": {
    "wm_update": "if r > 0.5:\n    w[s, :] = 0.0\n    w[s, a] = 1.0\nelse:\n    w[s, a] = max(1e-10, (1.0 - 0.2) * w[s, a])\n    asymmetric_fixed_wm_update_sum = np.sum(w[s, :])\n    if asymmetric_fixed_wm_update_sum > 0:\n        w[s, :] /= asymmetric_fixed_wm_update_sum"
