    "pre_choice": "dynamic_arbitration_load_term = max(0.0, float(nS - 3))\ndynamic_arbitration_logit = wm_base + surprise_gain * dynamic_arbitration_surprise - arb_load_scale * dynamic_arbitration_load_term\ndynamic_arbitration_weight = 1.0 / (1.0 + np.exp(-dynamic_arbitration_logit))",
