  {
   "id": "arbitration_gated_wm_learning",
   "name": "Arbitration-Gated WM Learning",
   "description": "The learning rate for updating working memory is scaled by the current trial's arbitration weight, meaning WM learns more when it is relied upon.",
   "params": [
    {
     "name": "wm_learn",
     "bounds": [
      0,
      1
     ]
    }
   ],
   "slots": {},
